import type { ComponentType } from 'react';
import type { CodeViewProps } from './svg-view';
import { isHighlighted } from './highlight';

/**
 * The code kinds (D-257): an SVG artifact (preview from a blob URL, or its source) and a CSV artifact (a table). Both draw inside the
 * panel's viewer bar, with its copy and download. This module is cheap; each view loads the first time its artifact opens. A source file (TypeScript, JavaScript, Python, shell, JSON) is drawn with its syntax coloured and its lines numbered (`codeKind`, no highlighter dependency).
 * Other text stays in the panel's own code block.
 */
export interface CodeKind {
  readonly match: (target: { readonly resource: { readonly path: string } }, artifact: { readonly type: string; readonly language?: string | undefined }) => boolean;
  readonly label?: string | undefined;
  /** A default viewer for a type: a host's `viewers.svg` or `viewers.code` wins over it. */
  readonly fallback: true;
  readonly load: () => Promise<{ readonly default: ComponentType<CodeViewProps> }>;
}

export const svgKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'svg',
  fallback: true,
  load: () => import('./svg-view').then(module => ({ default: module.SvgView })),
};

export const csvKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'code' && artifact.language === 'csv',
  fallback: true,
  load: () => import('./csv-table').then(module => ({ default: module.CsvView })),
};

/** Source code in a language `highlight.ts` knows: coloured and numbered, display only. */
export const codeKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'code' && isHighlighted(artifact.language),
  fallback: true,
  load: () => import('./code-view').then(module => ({ default: module.CodeView })),
};

'use client';

import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { CodeXmlIcon, EyeIcon } from '../_shared/icons';
import { CodeBlock } from '../pi-chat/code-block';
import { ViewerToggle } from '../viewer-frame/viewer-frame';
import { useViewerText } from '../viewer-frame/viewer-window';

/** What the code kinds' views read of the panel's kind props (structurally `ArtifactKindViewProps` of pi-artifacts). */
export interface CodeViewProps {
  readonly text: string;
  readonly artifact: { readonly title: string };
  /** The panel bar's controls slot (the preview and source toggle goes there). */
  readonly setControls?: ((controls: ReactNode) => void) | undefined;
}

/** An SVG artifact: a preview, or its source. The preview is an image from a blob URL: it never becomes markup in this page, so its scripts cannot run. */
export function SvgView({ text, artifact, setControls }: CodeViewProps) {
  const { labels } = useViewerText();
  const [mode, setMode] = useState<'preview' | 'source'>('preview');
  const url = useMemo(() => URL.createObjectURL(new Blob([text], { type: 'image/svg+xml' })), [text]);
  useEffect(() => () => URL.revokeObjectURL(url), [url]);
  useEffect(() => {
    setControls?.(<ViewerToggle label={labels.view} value={mode} onChange={setMode} options={[
      { id: 'preview', label: labels.preview, text: labels.preview, icon: <EyeIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' },
      { id: 'source', label: labels.source, text: labels.source, icon: <CodeXmlIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' }]} />);
    return () => setControls?.(undefined);
  }, [setControls, mode, labels.view, labels.preview, labels.source]);
  return mode === 'preview'
    ? <div className="boring-viewer-checker flex h-full min-h-0 items-center justify-center overflow-auto p-6"><img data-testid="artifact-svg" src={url} alt={artifact.title} className="max-h-full max-w-full" /></div>
    : <div className="min-h-0 p-3"><CodeBlock code={text} language="svg" /></div>;
}

'use client';

import { useContext, useRef, useState } from 'react';
import type { MouseEvent, PointerEvent } from 'react';
import { AtIcon, CheckIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { RowReferenceContext, columnNames, rowKey } from './row-reference';
import type { TableRow as TableRowData } from './row-reference';
import type { CodeViewProps } from './svg-view';

/** Rows of a CSV text (comma or semicolon separated, double-quoted cells with `""` escapes), at most 2000. */
export function csvRows(text: string): string[][] {
  const rows: string[][] = []; let row: string[] = [], cell = '', quoted = false;
  for (let i = 0; i < text.length && rows.length < 2000; i++) {
    const c = text[i];
    if (quoted) { if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') quoted = false; else cell += c; }
    else if (c === '"') quoted = true;
    else if (c === ',' || c === ';') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if ((cell || row.length) && rows.length < 2000) { row.push(cell); rows.push(row); }
  return rows;
}

const LONG_PRESS_MS = 500;
const INTERACTIVE = 'button, [role=checkbox], input, a';

/**
 * A CSV artifact as a table: the first row is the header. Inside a `RowReferenceContext` each row has an « @ » action that references it in the assistant
 * (a tooltip on hover and focus, « Referenced » once it is in the field), and rows can be selected together (a checkbox on hover or focus, Shift or Ctrl and
 * Cmd click, a long press on touch, or a plain click once one is checked) to reference them with one action.
 */
export function CsvView({ text }: CodeViewProps) {
  const [head = [], ...rows] = csvRows(text);
  const target = useContext(RowReferenceContext);
  const names = columnNames(head);
  const [selected, setSelected] = useState<ReadonlySet<number>>(new Set());
  const anchor = useRef(0), press = useRef<{ timer: ReturnType<typeof setTimeout>; fired: boolean } | undefined>(undefined);
  const data = (at: number): TableRowData => ({ row: at + 1, cells: Object.fromEntries(names.map((name, j) => [name, rows[at]?.[j] ?? ''])) });
  const toggle = (at: number, on?: boolean) => setSelected(current => { const next = new Set(current); if (on ?? !next.has(at)) next.add(at); else next.delete(at); return next; });
  const choose = (event: MouseEvent, at: number) => {
    if ((event.target as Element).closest(INTERACTIVE)) return;
    if (event.shiftKey && selected.size > 0) {
      const [from, to] = [Math.min(anchor.current, at), Math.max(anchor.current, at)];
      setSelected(current => new Set([...current, ...Array.from({ length: to - from + 1 }, (_, k) => from + k)]));
    } else if (event.shiftKey || event.ctrlKey || event.metaKey || selected.size > 0) { toggle(at); anchor.current = at; }
  };
  const startPress = (event: PointerEvent, at: number) => {
    if (event.pointerType !== 'touch' || (event.target as Element).closest(INTERACTIVE)) return;
    const timer = setTimeout(() => { if (press.current) press.current.fired = true; toggle(at); anchor.current = at; }, LONG_PRESS_MS);
    press.current = { timer, fired: false };
  };
  const endPress = () => { if (press.current) clearTimeout(press.current.timer); };
  const count = selected.size;
  return <div data-testid="artifact-csv-view" className="relative">
    <Table data-testid="artifact-csv">
      <TableHeader><TableRow>
        {target && <TableHead className="w-8"><span className="sr-only">{target.words.selectRow}</span></TableHead>}
        {head.map((cell, i) => <TableHead key={i}>{cell}</TableHead>)}
        {target && <TableHead className="w-10"><span className="sr-only">{target.words.reference}</span></TableHead>}
      </TableRow></TableHeader>
      <TableBody>{rows.map((row, i) => {
        const done = target?.referenced.has(rowKey(target.path, i + 1)) ?? false;
        return <TableRow key={i} className="group/row" data-row={i + 1} data-selected={selected.has(i) || undefined}
          onClick={target ? event => choose(event, i) : undefined} onPointerDown={target ? event => startPress(event, i) : undefined}
          onPointerUp={endPress} onPointerLeave={endPress} onPointerCancel={endPress} onContextMenu={target ? event => { if (press.current?.fired) { event.preventDefault(); press.current.fired = false; } } : undefined}>
          {target && <TableCell className="align-middle">
            <span className={count > 0 ? undefined : 'pointer-fine:opacity-0 pointer-fine:group-hover/row:opacity-100 pointer-fine:group-focus-within/row:opacity-100 max-md:hidden pointer-coarse:hidden'}>
              <Checkbox data-testid="csv-row-select" aria-label={`${target.words.selectRow} ${i + 1}`} checked={selected.has(i)} onCheckedChange={on => { toggle(i, on); anchor.current = i; }} />
            </span>
          </TableCell>}
          {row.map((cell, j) => <TableCell key={j} className="align-top">{cell}</TableCell>)}
          {target && <TableCell className="align-middle">
            <Tooltip>
              <TooltipTrigger render={<Button type="button" variant="ghost" size="icon-sm" data-testid="csv-row-reference" data-referenced={done || undefined} aria-pressed={done}
                aria-label={`${done ? target.words.referenced : target.words.reference} ${i + 1}`}
                className="pointer-fine:opacity-0 pointer-fine:group-hover/row:opacity-100 pointer-fine:group-focus-within/row:opacity-100 focus-visible:opacity-100 data-[referenced]:opacity-100"
                onClick={() => { if (!done) target.reference([data(i)]); }} />}>
                {done ? <CheckIcon aria-hidden="true" /> : <AtIcon aria-hidden="true" />}
              </TooltipTrigger>
              <TooltipContent side="top">{done ? target.words.referenced : target.words.reference}</TooltipContent>
            </Tooltip>
          </TableCell>}
        </TableRow>;
      })}</TableBody>
    </Table>
    {target && count > 0 && <div role="toolbar" data-testid="csv-selection-bar" className="sticky bottom-0 flex items-center gap-2 bg-muted p-2">
      <Button type="button" size="sm" data-testid="csv-reference-selected"
        onClick={() => { target.reference([...selected].sort((a, b) => a - b).map(data)); setSelected(new Set()); }}>{target.words.referenceRows.replace('{n}', String(count))}</Button>
      <Button type="button" variant="ghost" size="sm" onClick={() => setSelected(new Set())}>{target.words.clearSelection}</Button>
    </div>}
  </div>;
}

'use client';

import { createContext } from 'react';
import { mentionedPaths } from '@hachej/boring-ui-kit/chat-text';
import { TableIcon } from '../_shared/icons';
import type { MentionKind } from '../pi-chat/config';

/** One row of a table file: its number (the first row under the header is 1) and its cells by column. */
export interface TableRow {
  readonly row: number;
  readonly cells: Readonly<Record<string, string>>;
}

/** What the assistant receives for one mention: a file and the rows of it the person referenced, in the order they were chosen. */
export interface RowReference {
  readonly path: string;
  readonly rows: readonly TableRow[];
}

/** The action's words (the shell's, in the app's language) and what a table view needs to offer « reference in the assistant ». Absent: the table has no action. */
export interface RowReferenceWords {
  readonly reference: string;
  readonly referenced: string;
  /** `{n}` is the number of rows. */
  readonly referenceRows: string;
  readonly selectRow: string;
  readonly clearSelection: string;
}
export interface RowReferenceTarget {
  readonly path: string;
  readonly words: RowReferenceWords;
  /** The `rowKey`s already in the assistant's field: their buttons read as referenced. */
  readonly referenced: ReadonlySet<string>;
  /** Adds the rows to the field, after what is there. */
  readonly reference: (rows: readonly TableRow[]) => void;
}
export const RowReferenceContext = createContext<RowReferenceTarget | null>(null);

/** The mention prefix of a row reference: `@row:<path>#<rows> <cells as JSON>` (a value with spaces is written in quotes, as any mention is). */
export const ROW_MENTION = 'row';
/** More new rows than this go to the field as one grouped chip; up to this many get a chip each. */
export const GROUP_AFTER = 3;
const VALUE = /^(.+?)#(\d+(?:,\d+)*) (\{.*\}|\[.*\])$/s;

export const rowKey = (path: string, row: number): string => `${path}#${row}`;

/** A header row's names, each made unique so two columns called alike keep both cells. */
export function columnNames(head: readonly string[]): string[] {
  const seen = new Map<string, number>();
  return head.map((cell, at) => {
    const name = cell.trim() || `column ${at + 1}`;
    const count = (seen.get(name) ?? 0) + 1;
    seen.set(name, count);
    return count === 1 ? name : `${name} (${count})`;
  });
}

/** The mention's value without its `row:` prefix: the rows' numbers, then the cells (one object for one row, an array of objects, in the same order, for several). */
export const rowReferenceValue = ({ path, rows }: RowReference): string =>
  `${path}#${rows.map(item => item.row).join(',')} ${JSON.stringify(rows.length === 1 ? rows[0]!.cells : rows.map(item => item.cells))}`;
/** The `@` mention text for a row reference, prefix included, ready for `mentionToken`. */
export const rowMentionPath = (reference: RowReference): string => `${ROW_MENTION}:${rowReferenceValue(reference)}`;

const isCells = (value: unknown): value is Record<string, string> =>
  typeof value === 'object' && value !== null && !Array.isArray(value) && Object.values(value).every(cell => typeof cell === 'string');

/** The reference a mention value (without its prefix) stands for; undefined when it is not a well-formed row reference. */
export function parseRowReference(value: string): RowReference | undefined {
  const match = VALUE.exec(value);
  if (!match) return undefined;
  try {
    const numbers = match[2]!.split(',').map(Number), parsed = JSON.parse(match[3]!) as unknown;
    const all = numbers.length === 1 && isCells(parsed) ? [parsed] : Array.isArray(parsed) && parsed.length === numbers.length && parsed.every(isCells) ? parsed as Record<string, string>[] : undefined;
    return all ? { path: match[1]!, rows: numbers.map((row, at) => ({ row, cells: all[at]! })) } : undefined;
  } catch { return undefined; }
}

/** The `rowKey` of every row the text's `row` mentions cover. */
export function referencedRows(text: string): Set<string> {
  const keys = new Set<string>();
  for (const value of mentionedPaths(text)) {
    const reference = value.startsWith(`${ROW_MENTION}:`) ? parseRowReference(value.slice(ROW_MENTION.length + 1)) : undefined;
    for (const item of reference?.rows ?? []) keys.add(rowKey(reference!.path, item.row));
  }
  return keys;
}

const fileName = (path: string) => path.split('/').at(-1) ?? path;
const filled = (cells: Readonly<Record<string, string>>) => Object.values(cells).filter(cell => cell.trim() !== '');
const rowsBadge = (rows: readonly TableRow[]) => rows.length === 1 ? `row ${rows[0]!.row}` : `rows ${rows.map(item => item.row).join(', ')}`;

/** The chip's identity and summary: « open-gaps.csv » with a « row 3 » badge, then « Card Harbor Garage · Jan 09 · $12.00 » (a group lists each row's first cell). */
export function rowReferenceChip(value: string): { readonly title: string; readonly badge?: string; readonly description?: string } {
  const reference = parseRowReference(value);
  if (!reference) return { title: value };
  const first = reference.rows.length === 1 ? filled(reference.rows[0]!.cells).slice(0, 3).join(' · ') : reference.rows.map(item => filled(item.cells)[0]).filter(Boolean).join(', ');
  return { title: fileName(reference.path), badge: rowsBadge(reference.rows), ...(first ? { description: first } : {}) };
}

/** The words of the mention in a sent message and in a name: « open-gaps.csv row 3: Card Harbor Garage, Jan 09 ». */
export function rowReferenceLabel(value: string): string {
  const reference = parseRowReference(value);
  if (!reference) return value;
  const first = reference.rows.length === 1 ? filled(reference.rows[0]!.cells).slice(0, 2).join(', ') : '';
  return `${fileName(reference.path)} ${rowsBadge(reference.rows)}${first ? `: ${first}` : ''}`;
}

/** The composer's chip and the sent message's mention for a row reference. The shell adds it to an app's `mentions.kinds` as `row`. */
export const rowMentionKind: MentionKind = {
  label: rowReferenceLabel,
  present: rowReferenceChip,
  icon: <TableIcon className="size-4" aria-hidden="true" />,
};

'use client';

import { useMemo } from 'react';
import { cn } from '../utils/utils';
import { tokenLines } from './highlight';
import type { TokenKind } from './highlight';
import type { CodeViewProps } from './svg-view';

const TONE: Readonly<Record<TokenKind, string>> = {
  comment: 'text-muted-foreground italic',
  string: 'text-chart-2',
  number: 'text-chart-4',
  keyword: 'text-chart-1 font-medium',
};

/**
 * A code file read as text, with its comments, strings, numbers and keywords coloured (theme tokens, so light and dark follow the page) and
 * its lines numbered. Display only: the text is rendered as text nodes, never as markup, never evaluated. Long lines wrap on a phone and
 * scroll beside the numbers from `md` up.
 */
export function CodeView({ text, artifact }: CodeViewProps) {
  const language = artifact.title.includes('.') ? artifact.title.split('.').pop()!.toLowerCase() : undefined;
  const lines = useMemo(() => tokenLines(text, language), [text, language]);
  const digits = String(lines.length).length;
  return <div data-testid="artifact-code" data-language={language} className="min-h-0 overflow-x-auto text-xs leading-5">
    <ol className="m-0 min-w-fit list-none p-0">
      {lines.map((line, index) => <li key={index} className="flex">
        <span aria-hidden="true" data-mono-id className="font-mono sticky left-0 shrink-0 select-none bg-card pr-3 text-right text-muted-foreground tabular-nums" style={{ minWidth: `${digits + 1}ch` }}>{index + 1}</span>
        <code className="min-w-0 font-mono break-words whitespace-pre-wrap md:break-normal md:whitespace-pre">{line.length ? line.map((token, at) => token.kind ? <span key={at} className={cn(TONE[token.kind])}>{token.text}</span> : token.text) : '\n'}</code>
      </li>)}
    </ol>
  </div>;
}

// A small, dependency-free tokenizer for the code viewer: comments, strings, numbers and keywords of the languages a workspace holds most
// (TypeScript and JavaScript, Python, shell, JSON). It reads text and returns plain tokens; nothing here is markup, and nothing runs.
export type TokenKind = 'comment' | 'string' | 'number' | 'keyword';
export interface Token { readonly text: string; readonly kind?: TokenKind | undefined }

interface Grammar { readonly pattern: RegExp; readonly keywords: ReadonlySet<string> }

const words = (list: string) => new Set(list.split(' '));
const JS_KEYWORDS = words('as async await break case catch class const continue declare default delete do else enum export extends false finally for from function if implements import in instanceof interface let new null of private protected public readonly return static super switch this throw true try type typeof undefined var void while yield');
const PY_KEYWORDS = words('and as assert async await break class continue def del elif else except False finally for from global if import in is lambda None nonlocal not or pass raise return True try while with yield');
const SH_KEYWORDS = words('case do done elif else esac exit export fi for function if in local return select then until while');
const JSON_KEYWORDS = words('true false null');

// One alternation per language, tried at each position in order: the first group that matches names the token.
const NUMBER = String.raw`\b(?:0[xX][\da-fA-F_]+|\d[\d_]*(?:\.\d+)?(?:[eE][+-]?\d+)?)\b`;
const WORD = String.raw`[A-Za-z_$][\w$]*`;
const grammar = (comment: string, string: string, keywords: ReadonlySet<string>): Grammar => ({ keywords, pattern: new RegExp(`(${comment})|(${string})|(${NUMBER})|(${WORD})`, 'y') });

const JS = grammar(String.raw`\/\/[^\n]*|\/\*[\s\S]*?(?:\*\/|$)`, String.raw`"(?:\\.|[^"\\\n])*"?|'(?:\\.|[^'\\\n])*'?|\`(?:\\[\s\S]|[^\`\\])*\`?`, JS_KEYWORDS);
const PY = grammar(String.raw`#[^\n]*`, String.raw`(?:[rbfRBF]{0,2})(?:"""[\s\S]*?(?:"""|$)|'''[\s\S]*?(?:'''|$)|"(?:\\.|[^"\\\n])*"?|'(?:\\.|[^'\\\n])*'?)`, PY_KEYWORDS);
const SH = grammar(String.raw`#[^\n]*`, String.raw`"(?:\\[\s\S]|[^"\\])*"?|'[^']*'?`, SH_KEYWORDS);
const JSON_G = grammar(String.raw`(?!)`, String.raw`"(?:\\.|[^"\\\n])*"?`, JSON_KEYWORDS);

const GRAMMARS: Readonly<Record<string, Grammar>> = Object.assign(Object.create(null), {
  ts: JS, tsx: JS, js: JS, jsx: JS, mjs: JS, cjs: JS, mts: JS, cts: JS,
  py: PY, sh: SH, bash: SH, zsh: SH, json: JSON_G,
});

/** Is this file extension one the viewer colours? */
export const isHighlighted = (language: string | undefined): boolean => language !== undefined && language in GRAMMARS;

/** Files past this size stay plain: colouring is for reading a file, not for a data dump. */
export const HIGHLIGHT_LIMIT = 200_000;

/** The text split into tokens that join back to it exactly. An unknown language, or a text past the limit, is one plain token. */
export function tokenize(text: string, language: string | undefined): readonly Token[] {
  const rules = language !== undefined && language in GRAMMARS ? GRAMMARS[language] : undefined;
  if (!rules || text.length > HIGHLIGHT_LIMIT) return [{ text }];
  const out: Token[] = [];
  let plain = '';
  const flush = () => { if (plain) { out.push({ text: plain }); plain = ''; } };
  let at = 0;
  const { pattern } = rules;
  while (at < text.length) {
    pattern.lastIndex = at;
    const match = pattern.exec(text);
    if (match && match[0] !== '') {
      const kind: TokenKind | undefined = match[1] !== undefined ? 'comment' : match[2] !== undefined ? 'string' : match[3] !== undefined ? 'number' : rules.keywords.has(match[0]) ? 'keyword' : undefined;
      if (kind) { flush(); out.push({ text: match[0], kind }); } else plain += match[0];
      at += match[0].length;
    } else { plain += text[at]; at += 1; }
  }
  flush();
  return out;
}

/** Tokens grouped by line (a comment or string that spans lines is cut at each break), so a viewer can number and wrap each line itself. */
export function tokenLines(text: string, language: string | undefined): readonly (readonly Token[])[] {
  const lines: Token[][] = [[]];
  for (const token of tokenize(text, language)) {
    token.text.split('\n').forEach((part, index) => {
      if (index > 0) lines.push([]);
      if (part) lines.at(-1)!.push({ text: part, kind: token.kind });
    });
  }
  if (lines.length > 1 && lines.at(-1)!.length === 0) lines.pop();
  return lines;
}
